"use client";

import { useEffect, useId, useRef, useState } from "react";
import { cn } from "@/components/ui/cn";
import { fmt } from "@/lib/rechner/annahmen";

/* ------------------------------------------------------------------
   Gemeinsame Bedienelemente aller Rechner unter /rechner
   ------------------------------------------------------------------ */

const bewegungReduziert = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Zahl, die bei Änderungen weich zum neuen Wert gleitet.
 * Server-HTML enthält den Endwert; bei reduzierter Bewegung springt sie direkt.
 */
export function Zahl({ wert, stellen = 0, prefix = "", suffix = "", className, dauer = 520 }) {
  const ziel = Number.isFinite(wert) ? wert : 0;
  const [anzeige, setAnzeige] = useState(ziel);
  const aktuell = useRef(ziel);

  useEffect(() => {
    if (bewegungReduziert()) {
      aktuell.current = ziel;
      setAnzeige(ziel);
      return;
    }
    const von = aktuell.current;
    if (Math.abs(von - ziel) < 1e-9) return;
    let raf;
    const start = performance.now();
    const schritt = (t) => {
      const p = Math.min((t - start) / dauer, 1);
      const e = 1 - Math.pow(1 - p, 3);
      const v = von + (ziel - von) * e;
      aktuell.current = v;
      setAnzeige(v);
      if (p < 1) raf = requestAnimationFrame(schritt);
    };
    raf = requestAnimationFrame(schritt);
    return () => cancelAnimationFrame(raf);
  }, [ziel, dauer]);

  if (!Number.isFinite(wert)) return <span className={cn("ov-num", className)}>–</span>;
  return (
    <span className={cn("ov-num", className)}>
      {prefix}
      {fmt(anzeige, stellen)}
      {suffix}
    </span>
  );
}

/** Schieberegler mit großem Griff, Wertanzeige und Min/Max-Beschriftung. */
export function Regler({ label, wert, min, max, step = 1, einheit, onChange, hinweis, format, stellen = 0, dunkel = false, minLabel, maxLabel }) {
  const id = useId();
  const anteil = ((wert - min) / (max - min)) * 100;
  const text = format ? format(wert) : `${fmt(wert, stellen)}${einheit ? ` ${einheit}` : ""}`;
  return (
    <div>
      <div className="mb-3 flex items-baseline justify-between gap-3">
        <label htmlFor={id} className={cn("text-[14.5px] font-semibold", dunkel ? "text-white" : "text-ink-800")}>
          {label}
        </label>
        <output htmlFor={id} className={cn("ov-num shrink-0 font-display text-[17px] font-extrabold tracking-tight", dunkel ? "text-ov-300" : "text-ink-900")}>
          {text}
        </output>
      </div>
      <input
        id={id}
        type="range"
        min={min}
        max={max}
        step={step}
        value={wert}
        aria-valuetext={text}
        onChange={(e) => onChange(Number(e.target.value))}
        className="ov-range block cursor-pointer"
        // Große Trefferfläche (44 px), die sichtbare Spur bleibt 8 px hoch
        style={{
          "--ov-fill": `${Math.max(0, Math.min(100, anteil))}%`,
          height: 44,
          backgroundSize: "100% 8px",
          backgroundRepeat: "no-repeat",
          backgroundPosition: "center",
          borderRadius: 0,
        }}
      />
      <div className={cn("-mt-1.5 flex justify-between text-[12px]", dunkel ? "text-white/45" : "text-ink-500")}>
        <span>{minLabel ?? (format ? format(min) : `${fmt(min, stellen)}${einheit ? ` ${einheit}` : ""}`)}</span>
        <span>{maxLabel ?? (format ? format(max) : `${fmt(max, stellen)}${einheit ? ` ${einheit}` : ""}`)}</span>
      </div>
      {hinweis && <p className="mt-2 text-[13px] leading-relaxed text-ink-500">{hinweis}</p>}
    </div>
  );
}

/** Segmentierte Auswahl (echte Radio-Inputs, per Tastatur bedienbar). */
export function Auswahl({ legende, optionen, wert, onChange, spalten, klein = false }) {
  const name = useId();
  return (
    <fieldset>
      {legende && <legend className="mb-2.5 text-[14.5px] font-semibold text-ink-800">{legende}</legend>}
      <div
        className={cn("grid gap-1.5 rounded-2xl bg-ink-100/80 p-1.5")}
        style={{ gridTemplateColumns: `repeat(${spalten || optionen.length}, minmax(0, 1fr))` }}
      >
        {optionen.map((o) => {
          const aktiv = wert === o.id;
          return (
            <label
              key={o.id}
              className={cn(
                "relative flex min-h-11 cursor-pointer flex-col items-center justify-center rounded-xl px-2 py-1.5 text-center leading-tight transition-all duration-200 has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ov-500",
                klein ? "text-[13px]" : "text-[14px]",
                aktiv ? "bg-white font-semibold text-ink-900 shadow-[0_2px_8px_-2px_rgba(21,26,36,0.18)] ring-1 ring-ink-200/70" : "text-ink-600 hover:text-ink-800"
              )}
            >
              <input type="radio" name={name} value={o.id} checked={aktiv} onChange={() => onChange(o.id)} className="sr-only" />
              <span>{o.label}</span>
              {o.sub && <span className={cn("mt-0.5 text-[11.5px] font-normal", aktiv ? "text-ov-700" : "text-ink-500")}>{o.sub}</span>}
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

/** Ein/Aus-Schalter mit Icon und optionaler Zusatzzeile. */
export function Schalter({ label, beschreibung, an, onChange, icon: Icon, children }) {
  const id = useId();
  return (
    <div className={cn("rounded-2xl ring-1 transition-colors", an ? "bg-white ring-ov-300" : "bg-white/60 ring-ink-200")}>
      <label htmlFor={id} className="flex min-h-14 cursor-pointer items-center gap-3 px-4 py-3">
        {Icon && (
          <span className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition-colors", an ? "bg-ov-500 text-white" : "bg-ink-100 text-ink-500")}>
            <Icon aria-hidden="true" className="h-[18px] w-[18px]" />
          </span>
        )}
        <span className="min-w-0 flex-1">
          <span className="block text-[14.5px] font-semibold text-ink-800">{label}</span>
          {beschreibung && <span className="block text-[12.5px] leading-snug text-ink-500">{beschreibung}</span>}
        </span>
        <input id={id} type="checkbox" role="switch" checked={an} onChange={(e) => onChange(e.target.checked)} className="peer sr-only" />
        <span
          aria-hidden="true"
          className={cn(
            "relative h-7 w-12 shrink-0 rounded-full transition-colors duration-300 peer-focus-visible:ring-2 peer-focus-visible:ring-ov-500 peer-focus-visible:ring-offset-2",
            an ? "bg-ov-500" : "bg-ink-300"
          )}
        >
          <span className={cn("absolute top-1 h-5 w-5 rounded-full bg-white shadow transition-transform duration-300", an ? "translate-x-6" : "translate-x-1")} />
        </span>
      </label>
      {an && children && <div className="border-t border-ink-100 px-4 pb-4 pt-3">{children}</div>}
    </div>
  );
}

/** Überschrift eines Eingabeblocks */
export function Gruppe({ titel, children, className }) {
  return (
    <div className={cn("space-y-5", className)}>
      {titel && <p className="text-[11.5px] font-semibold uppercase tracking-[0.16em] text-ink-500">{titel}</p>}
      {children}
    </div>
  );
}

/** Beobachtet die Breite eines Elements (für Diagramme ohne Skalierung der Schrift). */
export function useBreite(standard = 720) {
  const ref = useRef(null);
  const [breite, setBreite] = useState(standard);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => {
      const w = Math.round(e.contentRect.width);
      if (w > 0) setBreite(w);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, breite];
}

/** Kennzahl-Kachel */
export function Kennzahl({ label, children, zusatz, icon: Icon, ton = "hell", className }) {
  const toene = {
    hell: "bg-white ring-1 ring-ink-200/70 text-ink-900",
    gruen: "bg-ov-600 text-white",
    navy: "bg-navy-950 text-white",
    sand: "bg-sand-50 ring-1 ring-ink-200/60 text-ink-900",
  };
  const dunkel = ton === "gruen" || ton === "navy";
  return (
    <div className={cn("relative overflow-hidden rounded-2xl p-4 md:p-5", toene[ton], className)}>
      <p className={cn("flex items-center gap-1.5 text-[12.5px] font-medium", ton === "gruen" ? "text-white" : dunkel ? "text-white/75" : "text-ink-500")}>
        {Icon && <Icon aria-hidden="true" className={cn("h-3.5 w-3.5", dunkel ? "text-white/80" : "text-ov-600")} />}
        {label}
      </p>
      <p className="mt-1 whitespace-nowrap font-display text-[clamp(1.4rem,1.15rem+0.7vw,1.85rem)] font-extrabold leading-tight tracking-tight">{children}</p>
      {zusatz && <p className={cn("mt-1 text-[12.5px] leading-snug", ton === "gruen" ? "text-white" : dunkel ? "text-white/70" : "text-ink-500")}>{zusatz}</p>}
    </div>
  );
}

/** Diagramm-Tooltip (absolut positioniert im relativen Container) */
export function Tooltip({ x, y, breite, children }) {
  const links = x > breite / 2;
  return (
    <div
      role="status"
      className="pointer-events-none absolute z-10 min-w-[150px] rounded-xl bg-ink-900 px-3.5 py-2.5 text-[12.5px] leading-relaxed text-white shadow-xl"
      style={{ top: Math.max(y, 0), ...(links ? { right: breite - x + 14 } : { left: x + 14 }) }}
    >
      {children}
    </div>
  );
}
import Link from "next/link";
import { ArrowUpRight, Info } from "lucide-react";
import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Reveal from "@/components/ui/Reveal";
import Querverweise from "@/components/Reusable/Querverweise";
import { TOOLS } from "./tools";
import { STAND } from "@/lib/rechner/annahmen";

import { SITE } from "@/data/site";

const BASE = SITE.url;

/** Metadaten für eine Rechner-Seite */
export function rechnerMetadata({ pfad, title, description, keywords = [] }) {
  const url = `${BASE}${pfad}`;
  return {
    title,
    description,
    keywords,
    alternates: { canonical: url },
    robots: { index: true, follow: true },
    openGraph: {
      type: "website",
      url,
      siteName: "ÖkoInvest",
      title,
      description,
      images: [{ url: `${BASE}/img/solarpark-himmel.jpg`, width: 1280, height: 852, alt: title }],
    },
    twitter: { card: "summary_large_image", title, description, images: [`${BASE}/img/solarpark-himmel.jpg`] },
  };
}

/**
 * Gemeinsamer Seitenrahmen aller Rechner: kompakter dunkler Hero, Rechner
 * überlappend darunter (above the fold), Erklärung + Annahmen, FAQ,
 * weitere Tools, Querverweise und Abschluss-CTA. Liefert WebApplication-Schema.
 */
export default function RechnerSeite({
  pfad,
  toolId,
  breadcrumb,
  eyebrow,
  title,
  lead,
  chips = [],
  app,
  rechner,
  erklaerung,
  annahmen = [],
  quellen = [],
  faq = [],
  faqTitel = "Häufige Fragen",
  querverweise = [],
  cta,
}) {
  const url = `${BASE}${pfad}`;
  const schema = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "WebApplication",
        "@id": `${url}/#app`,
        name: app.name,
        url,
        description: app.description,
        applicationCategory: "FinanceApplication",
        operatingSystem: "Web",
        browserRequirements: "Requires JavaScript",
        inLanguage: "de-DE",
        isAccessibleForFree: true,
        featureList: app.featureList,
        offers: { "@type": "Offer", price: "0", priceCurrency: "EUR" },
        publisher: { "@id": `${BASE}/#organization` },
      },
      {
        "@type": "WebPage",
        "@id": `${url}/#webpage`,
        url,
        name: app.name,
        isPartOf: { "@id": `${BASE}/#website` },
        about: { "@id": `${BASE}/#organization` },
        dateModified: new Date().toISOString().split("T")[0],
        mainEntity: { "@id": `${url}/#app` },
      },
    ],
  };

  return (
    <div>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />

      <PageHero
        variant="dark"
        breadcrumbs={[{ name: "Rechner & Tools", href: "/rechner" }, { name: breadcrumb }]}
        eyebrow={eyebrow}
        title={title}
        lead={lead}
        points={chips}
        className="[&>div.ov-container]:pb-28 md:[&>div.ov-container]:pb-36"
      />

      {/* Rechner überlappt den Hero – sofort sichtbar */}
      <section aria-label="Rechner" className="relative z-10 -mt-20 pb-6 md:-mt-28 md:pb-10">
        <div className="ov-container">{rechner}</div>
      </section>

      <Section tone="white" space="md">
        <div className="grid gap-10 lg:grid-cols-[1.1fr_0.9fr] lg:gap-16">
          <div>{erklaerung}</div>
          <Reveal>
            <AnnahmenBox punkte={annahmen} quellen={quellen} />
          </Reveal>
        </div>
      </Section>

      {faq.length > 0 && (
        <Section tone="sand" space="md">
          <div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
            <SectionHeading
              eyebrow="Häufige Fragen"
              title={faqTitel}
              lead="Ihre Frage ist nicht dabei? Unser Projektteam beantwortet sie persönlich."
            />
            <Faq items={faq} />
          </div>
        </Section>
      )}

      <WeitereRechner ohne={toolId} />
      <Querverweise items={querverweise} />
      <CtaBand {...cta} />
    </div>
  );
}

export function AnnahmenBox({ punkte = [], quellen = [] }) {
  return (
    <aside aria-labelledby="annahmen-titel" className="rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/70 md:p-8">
      <div className="flex items-center gap-3">
        <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-ov-600 ring-1 ring-ink-200">
          <Info aria-hidden="true" className="h-5 w-5" />
        </span>
        <div>
          <h2 id="annahmen-titel" className="font-display text-[19px] font-bold text-ink-900">Annahmen & Grenzen</h2>
          <p className="text-[12.5px] text-ink-500">Stand {STAND} · Orientierung, kein Angebot</p>
        </div>
      </div>
      <dl className="mt-6 divide-y divide-ink-200/70">
        {punkte.map(([k, v]) => (
          <div key={k} className="flex items-baseline justify-between gap-4 py-2.5 text-[14px]">
            <dt className="text-ink-600">{k}</dt>
            <dd className="ov-num shrink-0 text-right font-semibold text-ink-900">{v}</dd>
          </div>
        ))}
      </dl>
      {quellen.length > 0 && (
        <p className="mt-5 text-[12.5px] leading-relaxed text-ink-500">
          Quellen: {quellen.map((q, i) => (
            <span key={q.name}>
              {i > 0 && " · "}
              {q.url ? (
                <a href={q.url} target="_blank" rel="noopener noreferrer" className="underline decoration-ink-300 underline-offset-2 hover:text-ink-800">
                  {q.name}
                </a>
              ) : (
                q.name
              )}
            </span>
          ))}
        </p>
      )}
    </aside>
  );
}

export function WeitereRechner({ ohne, titel = "Weitere Rechner & Tools" }) {
  const liste = TOOLS.filter((t) => t.id !== ohne).slice(0, 6);
  return (
    <section aria-labelledby="weitere-rechner" className="bg-white">
      <div className="ov-container pt-16 md:pt-24">
        <div className="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-ink-200 pb-6">
          <h2 id="weitere-rechner" className="ov-h3 text-ink-900 md:text-[28px]">{titel}</h2>
          <Link href="/rechner" className="inline-flex items-center gap-1.5 text-[15px] font-semibold text-ov-700 hover:text-ov-800">
            Alle Tools <ArrowUpRight aria-hidden="true" className="h-4 w-4" />
          </Link>
        </div>
        <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {liste.map((t, i) => {
            const Icon = t.icon;
            return (
              <Reveal as="li" key={t.id} delay={i * 60} className="flex">
                <Link
                  href={t.href}
                  className="group ov-card-hover flex w-full items-start gap-4 rounded-3xl bg-sand-50 p-5 ring-1 ring-ink-200/60 hover:bg-white"
                >
                  <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white text-ov-600 ring-1 ring-ink-200 transition-colors group-hover:bg-ov-500 group-hover:text-white group-hover:ring-ov-500">
                    <Icon aria-hidden="true" className="h-5 w-5" />
                  </span>
                  <span className="min-w-0">
                    <span className="block font-display text-[17px] font-bold leading-snug text-ink-900">{t.titel}</span>
                    <span className="mt-1 block text-[14px] leading-relaxed text-ink-600">{t.kurz}</span>
                  </span>
                </Link>
              </Reveal>
            );
          })}
        </ul>
      </div>
    </section>
  );
}
"use client";

import { cn } from "@/components/ui/cn";

/* ------------------------------------------------------------------
   Ergänzende Bausteine für die Investoren-, Carport- und Kommunal-
   Rechner (Solarpark, Projektbewertung, Solarcarport, Kommune).
   Die Grundbausteine stehen in ./bausteine.js.
   ------------------------------------------------------------------ */

/**
 * Äußerer Rahmen: Eingaben links (Sand), Ergebnis rechts. Bei `mitlaufend`
 * bleibt das Ergebnis am Desktop sichtbar, während links gescrollt wird.
 * `unten`: volle Breite unter beiden Spalten (Matrix, Tabellen).
 */
export function RechnerRahmen({ eingaben, ergebnis, unten, breiteLinks = 410, mitlaufend = false }) {
  return (
    <div className="overflow-clip rounded-[2rem] bg-white shadow-[0_40px_80px_-40px_rgba(3,18,43,0.45)] ring-1 ring-ink-200/70">
      <div className="grid lg:grid-cols-[minmax(0,var(--links))_minmax(0,1fr)]" style={{ "--links": `${breiteLinks}px` }}>
        <div className="relative border-b border-ink-100 bg-sand-50 p-5 sm:p-6 md:p-8 lg:border-b-0 lg:border-r">{eingaben}</div>
        <div className="min-w-0 p-5 sm:p-6 md:p-8">
          <div className={mitlaufend ? "lg:sticky lg:top-24" : undefined}>{ergebnis}</div>
        </div>
      </div>
      {unten && <div className="border-t border-ink-100 p-5 sm:p-6 md:p-8">{unten}</div>}
    </div>
  );
}

/** Kompakte, mitlaufende Ergebniszeile auf dem Handy (über den Eingaben) */
export function MobilKurz({ werte }) {
  return (
    <div className="sticky top-[76px] z-20 -mx-5 -mt-5 mb-6 border-b border-white/10 bg-navy-950/95 px-5 py-3 text-white backdrop-blur sm:-mx-6 sm:-mt-6 sm:px-6 lg:hidden">
      <dl className={cn("grid gap-2", werte.length === 4 ? "grid-cols-4" : "grid-cols-3")}>
        {werte.map(([k, v]) => (
          <div key={k} className="min-w-0">
            <dt className="truncate text-[11px] text-white/60">{k}</dt>
            <dd className="truncate font-display text-[16px] font-extrabold leading-tight tracking-tight min-[400px]:text-[17px]">{v}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

/** Überschrift des Ergebnisbereichs mit Status-Plakette */
export function ErgebnisKopf({ titel = "Ihr Ergebnis", plakette }) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3">
      <h2 className="font-display text-[22px] font-extrabold tracking-tight text-ink-900 md:text-[26px]">{titel}</h2>
      {plakette && (
        <span className="inline-flex items-center gap-2 rounded-full bg-ov-50 px-3 py-1 text-[12.5px] font-semibold text-ov-700 ring-1 ring-ov-200">
          <span className="h-1.5 w-1.5 rounded-full bg-ov-500" aria-hidden="true" />
          {plakette}
        </span>
      )}
    </div>
  );
}

/** Hinweiszeile im Ergebnis (neutral | warnung | gut) */
export function Hinweis({ ton = "neutral", icon: Icon, children, className }) {
  const toene = {
    neutral: "bg-ink-50 text-ink-700 ring-ink-200/70",
    warnung: "bg-sun-300/20 text-ink-800 ring-sun-400/50",
    gut: "bg-ov-50 text-ink-800 ring-ov-200",
  };
  return (
    <p className={cn("flex items-start gap-2.5 rounded-2xl px-4 py-3 text-[13.5px] leading-relaxed ring-1", toene[ton], className)}>
      {Icon && <Icon aria-hidden="true" className={cn("mt-0.5 h-4 w-4 shrink-0", ton === "warnung" ? "text-sun-500" : ton === "gut" ? "text-ov-600" : "text-ink-500")} />}
      <span className="min-w-0">{children}</span>
    </p>
  );
}

/** Umschalter für Diagramm-Ansichten (echte Radio-Buttons) */
export function Ansicht({ name, optionen, wert, onChange, label }) {
  return (
    <div role="radiogroup" aria-label={label} className="inline-flex rounded-full bg-ink-100 p-1">
      {optionen.map((o) => (
        <label
          key={o.id}
          className={cn(
            "cursor-pointer rounded-full px-3.5 py-1.5 text-[12.5px] font-semibold transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ov-500",
            wert === o.id ? "bg-white text-ink-900 shadow-sm" : "text-ink-600 hover:text-ink-900"
          )}
        >
          <input type="radio" name={name} value={o.id} checked={wert === o.id} onChange={() => onChange(o.id)} className="sr-only" />
          {o.label}
        </label>
      ))}
    </div>
  );
}

/** Legendenpunkt */
export function Legende({ items }) {
  return (
    <ul className="flex flex-wrap gap-x-5 gap-y-2 text-[12.5px] text-ink-600">
      {items.map((i) => (
        <li key={i.label} className="flex items-center gap-2">
          {i.linie ? (
            <span className="h-[3px] w-5 rounded-full" style={{ background: i.farbe }} aria-hidden="true" />
          ) : (
            <span className="h-3 w-3 rounded-[3px]" style={{ background: i.farbe }} aria-hidden="true" />
          )}
          {i.label}
        </li>
      ))}
    </ul>
  );
}

"use client";

import { useState } from "react";
import { CheckCircle2, CircleAlert, OctagonAlert, Printer } from "lucide-react";
