  "#37521e", // ov-800   ·  8.8:1
  "#6b7486", // ink-500  ·  4.7:1
];

/** Kategorien auf dunklem Grund (navy-950 / --ov-nacht-1). */
export const KATEGORIE_DUNKEL = [
  "#aed083", // ov-300   · 10.8:1
  "#7fa7d6", // navy-300 ·  7.5:1
  "#ffd873", // sun-300  · 13.6:1
