/* Schieberegler im Markenstil – für alle Rechner */
.ov-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 9999px;
  background: linear-gradient(to right, #669933 0%, #669933 var(--ov-fill, 50%), #dfe3ea var(--ov-fill, 50%), #dfe3ea 100%);
