@keyframes ov-wachsen-y { from { transform: scaleY(0); } to { transform: none; } }
@keyframes ov-wachsen-x { from { transform: scaleX(0); } to { transform: none; } }
@keyframes ov-zeichnen { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.ov-balken-y { transform-box: fill-box; transform-origin: 50% 100%; }
.ov-balken-x { transform-box: fill-box; transform-origin: 0% 50%; }
.ov-linie { stroke-dasharray: 1; stroke-dashoffset: 0; }
@media (prefers-reduced-motion: no-preference) {
  .js-ready .ov-reveal:not(.is-visible) .ov-balken-y { transform: scaleY(0); }
  .js-ready .ov-reveal:not(.is-visible) .ov-balken-x { transform: scaleX(0); }
  .js-ready .ov-reveal:not(.is-visible) .ov-linie { stroke-dashoffset: 1; }
  .js-ready .ov-reveal:not(.is-visible) .ov-flaeche-ein { opacity: 0; }
  .is-visible .ov-balken-y, .ov-sofort .ov-balken-y, .ov-balken-y.ov-sofort {
    animation: ov-wachsen-y var(--ov-dauer-xl) var(--ov-ease-out) both;
    animation-delay: calc(var(--i, 0) * 40ms + var(--ov-delay, 0ms));
  }
  .is-visible .ov-balken-x, .ov-sofort .ov-balken-x, .ov-balken-x.ov-sofort {
    animation: ov-wachsen-x var(--ov-dauer-xl) var(--ov-ease-out) both;
    animation-delay: calc(var(--i, 0) * 40ms + var(--ov-delay, 0ms));
  }
  .is-visible .ov-linie, .ov-sofort .ov-linie, .ov-linie.ov-sofort {
    animation: ov-zeichnen 1100ms var(--ov-ease-in-out) both;
    animation-delay: var(--ov-delay, 0ms);
  }
  .is-visible .ov-flaeche-ein, .ov-sofort .ov-flaeche-ein {
    animation: ov-einblenden 600ms var(--ov-ease-out) 500ms both;
  }
}

/* Fortschrittsring: Kreis mit pathLength="1", --ov-p = Anteil 0…1 */
  @keyframes ov-ring { from { stroke-dashoffset: var(--ov-p, 0); } to { stroke-dashoffset: 0; } }
  .ov-ring-wert { stroke-dasharray: var(--ov-p, 0) 1; stroke-dashoffset: 0; transition: stroke-dasharray var(--ov-dauer-xl) var(--ov-ease-out); }
  @media (prefers-reduced-motion: no-preference) {
    .js-ready .ov-reveal:not(.is-visible) .ov-ring-wert { stroke-dashoffset: var(--ov-p, 0); }
