  }

  /* Fortschritt per scaleX (kein width-Repaint) */
.ov-fortschritt { transform-origin: 0 50%; transition: transform var(--ov-dauer-xl) var(--ov-ease-out); }

/* Erfolgs-Feedback: Kreis federt, Haken zeichnet sich */
@keyframes ov-erfolg-pop { 0% { transform: scale(0.6); opacity: 0.001; } 60% { transform: scale(1.06); opacity: 1; } 100% { transform: none; opacity: 1; } }
