.ov-erfolg .ov-linie { animation: ov-zeichnen 420ms var(--ov-ease-out) 220ms both; }

/* Overlays: Dialog (natives <dialog>), Toast, Tooltip */
@keyframes ov-dialog-ein { from { opacity: 0.001; transform: translate3d(0, 12px, 0) scale(0.98); } to { opacity: 1; transform: none; } }
