          <p className="ov-kpi-l mt-2 whitespace-nowrap text-white">{children}</p>
          {zusatz && <p className="mt-1.5 text-[13.5px] leading-snug text-white/75">{zusatz}</p>}
        </div>
        {rechts && <div className="min-w-0 shrink-0">{rechts}</div>}
      </div>
    </div>
  );
