1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import Link from "next/link";
5	import {
6	  ArrowLeft, ArrowRight, Car, Check, CircleAlert, CircleMinus, CirclePlus, Factory, HandCoins, Info, Landmark, Mountain,
7	  Recycle, RotateCcw, ShieldAlert, Sprout, TrainFront, Trees, User, Users, Waves, Wheat,
8	} from "lucide-react";
9	import { cn } from "@/components/ui/cn";
10	import AnfrageFormular from "@/components/Plattform/AnfrageFormular";
11	import { Regler } from "@/components/Rechner/bausteine";
12	import { BESONDERHEITEN, EIGENTUM, LAENDER, NETZ, NUTZUNGEN, flaechencheck, regionenFuer } from "@/lib/rechner/flaechencheck";
13	import { AGRI, PACHT, STAND } from "@/lib/invest/markt";
14	import { fmt } from "@/lib/rechner/annahmen";
15	
16	const SCHRITTE = ["Standort", "Fläche", "Besonderheiten", "Netz & Eigentum"];
17	const NUTZUNG_ICON = { acker: Wheat, gruenland: Sprout, konversion: Factory, deponie: Recycle, parkplatz: Car, sonstige: Info };
18	const BES_ICON = { randstreifen: TrainFront, benachteiligt: Wheat, schutzgebiet: ShieldAlert, wald: Trees, hang: Mountain, ueberschwemmung: Waves };
19	const EIG_ICON = { allein: User, gemeinschaft: Users, verpachtet: HandCoins, kommune: Landmark };
20	const AMPEL = {
21	  gruen: { label: "Gut geeignet", text: "Ihre Fläche bringt gute Voraussetzungen mit. Jetzt lohnt die genaue Prüfung.", farbe: "#669933", ton: "bg-ov-500" },
22	  gelb: { label: "Bedingt geeignet", text: "Möglich – aber einzelne Punkte müssen wir genau prüfen, bevor es konkret wird.", farbe: "#ffc53d", ton: "bg-sun-400" },
23	  rot: { label: "Eher schwierig", text: "Als klassischer Solarpark schwierig. Oft gibt es trotzdem Wege – etwa Agri-PV, Nachbarflächen oder ein Carport.", farbe: "#c4cad5", ton: "bg-ink-300" },
24	};
25	const spanne = (a, b) => (b >= 1e6 ? `${fmt(a / 1e6, 2)}–${fmt(b / 1e6, 2)} Mio. €` : `${fmt(a / 1000)}–${fmt(b / 1000)} Tsd. €`);
26	
27	export default function FlaechenWizard() {
28	  const [schritt, setSchritt] = useState(0);
29	  const [richtung, setRichtung] = useState("vor");
30	  const [land, setLand] = useState(null);
31	  const [regionId, setRegionId] = useState(null);
32	  const [ha, setHa] = useState(10);
33	  const [nutzung, setNutzung] = useState(null);
34	  const [besonderheiten, setBesonderheiten] = useState([]);
35	  const [netz, setNetz] = useState(null);
36	  const [eigentum, setEigentum] = useState(null);
37	  const kopfRef = useRef(null);
38	  const ersterRender = useRef(true);
39	
40	  useEffect(() => {
41	    if (ersterRender.current) {
42	      ersterRender.current = false;
43	      return;
44	    }
45	    const el = kopfRef.current;
46	    if (!el) return;
47	    const top = el.getBoundingClientRect().top + window.scrollY - 110;
48	    if (Math.abs(window.scrollY - top) > 120) window.scrollTo({ top, behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
49	    el.focus({ preventScroll: true });
50	  }, [schritt]);
51	
52	  const regionen = land ? regionenFuer(land) : [];
53	  const weiterOk = [Boolean(land && regionId), Boolean(nutzung && ha > 0), true, Boolean(netz && eigentum)][schritt];
54	
55	  const ergebnis = useMemo(
56	    () => (schritt === 4 ? flaechencheck({ land, regionId, ha, nutzung, besonderheiten, netz, eigentum }) : null),
57	    [schritt, land, regionId, ha, nutzung, besonderheiten, netz, eigentum]
58	  );
59	
60	  function gehe(n) {
61	    setRichtung(n > schritt ? "vor" : "zurueck");
62	    setSchritt(n);
63	  }
64	
65	  function landWaehlen(id) {
66	    setLand(id);
67	    const r = regionenFuer(id);
68	    setRegionId(r.length === 1 ? r[0].id : r.find((x) => x.id === regionId)?.id || null);
69	  }
70	
71	  function umschalten(id) {
72	    setBesonderheiten((alt) => (alt.includes(id) ? alt.filter((x) => x !== id) : [...alt, id]));
73	  }
74	
75	  function neu() {
76	    setLand(null);
77	    setRegionId(null);
78	    setHa(10);
79	    setNutzung(null);
80	    setBesonderheiten([]);
81	    setNetz(null);
82	    setEigentum(null);
83	    gehe(0);
84	  }
85	
86	  const karte = (an) =>
87	    cn(
88	      "relative flex cursor-pointer items-center gap-3.5 rounded-3xl p-4 transition-all focus-within:ring-2 focus-within:ring-ov-500 sm:p-5",
89	      an ? "bg-ov-50 ring-2 ring-ov-500" : "bg-sand-50 ring-1 ring-ink-200 hover:bg-white hover:ring-ink-300"
90	    );
91	  const iconBox = (an) => cn("flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl transition-colors", an ? "bg-ov-500 text-white" : "bg-white text-ov-600 ring-1 ring-ink-200");
92	  const legende = "font-display text-[clamp(1.4rem,1.1rem+1vw,1.9rem)] font-extrabold tracking-tight text-ink-900";
93	
94	  return (
95	    <div className="overflow-hidden rounded-[2rem] bg-white shadow-[0_40px_90px_-50px_rgba(3,18,43,0.55)] ring-1 ring-ink-200/70">
96	      {/* Fortschritt */}
97	      <div ref={kopfRef} tabIndex={-1} className="border-b border-ink-100 bg-sand-50/70 px-5 py-5 outline-none sm:px-8 md:px-10">
98	        <ol className="flex items-center gap-2 sm:gap-3" aria-label="Fortschritt">
99	          {[...SCHRITTE, "Ergebnis"].map((s, i) => {
100	            const fertig = i < schritt;
101	            const aktiv = i === schritt;
102	            return (
103	              <li key={s} className="flex min-w-0 flex-1 items-center gap-2 sm:gap-3 last:flex-none" aria-current={aktiv ? "step" : undefined}>
104	                <button type="button" disabled={i > schritt} onClick={() => gehe(i)} className="flex min-w-0 items-center gap-2 rounded-full text-left disabled:cursor-default">
105	                  <span className={cn("flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-[13px] font-bold transition-colors", fertig ? "bg-ov-600 text-white" : aktiv ? "bg-navy-950 text-white" : "bg-white text-ink-500 ring-1 ring-ink-200")}>
106	                    {fertig ? <Check aria-hidden="true" className="h-4 w-4" strokeWidth={3} /> : i + 1}
107	                  </span>
108	                  <span className={cn("hidden truncate text-[14px] font-semibold xl:block", aktiv ? "text-ink-900" : fertig ? "text-ink-700" : "text-ink-500")}>{s}</span>
109	                  <span className="sr-only xl:hidden">{s}</span>
110	                </button>
111	                {i < 4 && <span aria-hidden="true" className={cn("h-px flex-1", fertig ? "bg-ov-400" : "bg-ink-200")} />}
112	              </li>
113	            );
114	          })}
115	        </ol>
116	      </div>
117	
118	      <div className="p-5 sm:p-8 md:p-10">
119	        <div key={schritt} className={richtung === "vor" ? "ov-step-vor" : "ov-step-zurueck"}>
120	          {/* 1 Standort */}
121	          {schritt === 0 && (
122	            <div className="space-y-8">
123	              <fieldset>
124	                <legend className={legende}>Wo liegt die Fläche?</legend>
125	                <p className="mt-2 text-[15.5px] text-ink-600">Land und Region bestimmen Einstrahlung, Förderung und Genehmigungsweg.</p>
126	                <div className="mt-6 grid grid-cols-3 gap-2 sm:gap-3">
127	                  {LAENDER.map((l) => {
128	                    const an = land === l.id;
129	                    return (
130	                      <label key={l.id} className={cn(karte(an), "flex-col gap-2 text-center sm:flex-row sm:text-left")}>
131	                        <input type="radio" name="land" value={l.id} checked={an} onChange={() => landWaehlen(l.id)} className="sr-only" />
132	                        <span className={cn(iconBox(an), "font-display text-[13px] font-extrabold")}>{l.id}</span>
133	                        <span className="text-[14.5px] font-semibold leading-tight text-ink-900">{l.label}</span>
134	                      </label>
135	                    );
136	                  })}
137	                </div>
138	              </fieldset>
139	              {land && regionen.length > 1 && (
140	                <fieldset className="ov-step-vor">
141	                  <legend className="text-[15px] font-semibold text-ink-800">Region</legend>
142	                  <div className="mt-3 grid gap-2 sm:grid-cols-2">
143	                    {regionen.map((r) => {
144	                      const an = regionId === r.id;
145	                      return (
146	                        <label key={r.id} className={cn(karte(an), "py-3.5 sm:py-4")}>
147	                          <input type="radio" name="region" value={r.id} checked={an} onChange={() => setRegionId(r.id)} className="sr-only" />
148	                          <span className="min-w-0 flex-1">
149	                            <span className="block text-[15px] font-semibold text-ink-900">{r.label}</span>
150	                            <span className="block text-[13px] text-ink-500">{r.sub}</span>
151	                          </span>
152	                          <span className="ov-num shrink-0 text-[12.5px] font-semibold text-ov-700">{fmt(r.ertrag)} kWh/kWp</span>
153	                        </label>
154	                      );
155	                    })}
156	                  </div>
157	                </fieldset>
158	              )}
159	            </div>
160	          )}
161	
162	          {/* 2 Fläche */}
163	          {schritt === 1 && (
164	            <div className="space-y-8">
165	              <div>
166	                <p className={legende}>Wie groß ist die Fläche?</p>
167	                <p className="mt-2 text-[15.5px] text-ink-600">Eine grobe Angabe genügt. Mehrere zusammenhängende Flurstücke zählen zusammen.</p>
168	                <div className="mt-6 grid items-end gap-5 sm:grid-cols-[1fr_auto]">
169	                  <Regler label="Flächengröße" wert={Math.min(ha, 150)} min={0.5} max={150} step={0.5} stellen={ha % 1 ? 1 : 0} einheit="ha" onChange={setHa} minLabel="0,5 ha" maxLabel="150 ha" />
170	                  <label className="block">
171	                    <span className="mb-1.5 block text-[13px] font-semibold text-ink-600">Genau eingeben</span>
172	                    <span className="relative block">
173	                      <input
174	                        type="number"
175	                        inputMode="decimal"
176	                        min={0.1}
177	                        max={2000}
178	                        step={0.1}
179	                        value={ha}
180	                        onChange={(e) => setHa(Math.max(0.1, Math.min(2000, Number(e.target.value) || 0.1)))}
181	                        className="ov-num h-12 w-full rounded-xl bg-sand-50 pl-4 pr-10 text-[16px] font-semibold text-ink-900 ring-1 ring-ink-200 focus:bg-white focus:outline-none focus:ring-2 focus:ring-ov-500 sm:w-36"
182	                      />
183	                      <span className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-[14px] text-ink-500">ha</span>
184	                    </span>
185	                  </label>
186	                </div>
187	              </div>
188	              <fieldset>
189	                <legend className="text-[15px] font-semibold text-ink-800">Wie wird die Fläche heute genutzt?</legend>
190	                <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
191	                  {NUTZUNGEN.map((n) => {
192	                    const an = nutzung === n.id;
193	                    const Icon = NUTZUNG_ICON[n.id];
194	                    return (
195	                      <label key={n.id} className={karte(an)}>
196	                        <input type="radio" name="nutzung" value={n.id} checked={an} onChange={() => setNutzung(n.id)} className="sr-only" />
197	                        <span className={iconBox(an)}>
198	                          <Icon aria-hidden="true" className="h-5 w-5" />
199	                        </span>
200	                        <span className="min-w-0">
201	                          <span className="block font-display text-[16px] font-bold text-ink-900">{n.label}</span>
202	                          <span className="block text-[13px] leading-snug text-ink-500">{n.text}</span>
203	                        </span>
204	                      </label>
205	                    );
206	                  })}
207	                </div>
208	              </fieldset>
209	            </div>
210	          )}
211	
212	          {/* 3 Besonderheiten */}
213	          {schritt === 2 && (
214	            <fieldset>
215	              <legend className={legende}>Trifft etwas davon zu?</legend>
216	              <p className="mt-2 text-[15.5px] text-ink-600">Mehrfachauswahl möglich. Wenn Sie es nicht wissen, lassen Sie es leer – wir prüfen das ohnehin.</p>
217	              <div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
218	                {BESONDERHEITEN.filter((b) => b.id !== "benachteiligt" || land === "DE").map((b) => {
219	                  const an = besonderheiten.includes(b.id);
220	                  const Icon = BES_ICON[b.id];
221	                  return (
222	                    <label key={b.id} className={karte(an)}>
223	                      <input type="checkbox" checked={an} onChange={() => umschalten(b.id)} className="sr-only" />
224	                      <span className={iconBox(an)}>
225	                        <Icon aria-hidden="true" className="h-5 w-5" />
226	                      </span>
227	                      <span className="min-w-0 pr-6">
228	                        <span className="block font-display text-[16px] font-bold leading-snug text-ink-900">{b.label}</span>
229	                        <span className="block text-[13px] leading-snug text-ink-500">{b.text}</span>
230	                      </span>
231	                      <span aria-hidden="true" className={cn("absolute right-4 top-4 flex h-6 w-6 items-center justify-center rounded-full transition-all", an ? "bg-ov-500 text-white" : "bg-white ring-1 ring-ink-300")}>
232	                        {an && <Check className="h-3.5 w-3.5" strokeWidth={3} />}
233	                      </span>
234	                    </label>
