export function Zahl({ wert, stellen = 0, prefix = "", suffix = "", format, className, dauer = 520, einlauf = false }) {
  const ziel = Number.isFinite(wert) ? wert : 0;
  const [anzeige, setAnzeige] = useState(ziel);
