                minLabel="5 %"
                maxLabel="49 %"
                onChange={(v) => set("egQuote")(v / 100)}
                hinweis={`Anteil am Eigenkapital der Parkgesellschaft. Genossenschaftskapital ≈ ${fmtEur(m.eg.egKapital)} bei ${fmt(m.park.ek / 1e6, 2)} Mio. € Eigenkapital des Parks.`}
