            <Kennzahl icon={Gauge} label="LCOE" zusatz={`Fraunhofer ISE 2024: ${fmt(ERLOESE.lcoeIseCt.min, 1)}–${fmt(ERLOESE.lcoeIseCt.max, 1)} ct`}>
              <Zahl wert={r.lcoeCt} stellen={2} suffix=" ct" />
