const FARBE = { erloes: "#669933", kosten: "#c4cad5", dienst: "#1f5aa1", cf: "#151a24", ek: "#669933", projekt: "#1f5aa1", raster: "#eef0f4" };
const pct = (v, s = 1) => (v == null || !Number.isFinite(v) ? "–" : `${fmt(v * 100, s)} %`);
const tsd = (v) => `${fmt(v / 1000)} T€`;

