// T2-Rechnertest: lädt Rechnerseiten per HTTP (wie curl), prüft Status 200
// und dass im sichtbaren Text kein „NaN“ oder „undefined“ steht.
// Aufruf: node t2-rechner-test.mjs [pfad …]
const BASIS = process.env.BASIS || "http://localhost:3100";
const PFADE = process.argv.slice(2).length
  ? process.argv.slice(2)
  : ["/rechner", "/rechner/solarpark", "/rechner/ppa", "/rechner/kommune", "/rechner/pachtangebot-check", "/flaechencheck"];

/** Sichtbarer Text: Skripte, Styles und JSON-Daten von Next entfernen, Tags weg. */
function sichtbarerText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<template[\s\S]*?<\/template>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ");
}

let fehler = 0;
for (const pfad of PFADE) {
  const start = Date.now();
  try {
    const res = await fetch(BASIS + pfad, { signal: AbortSignal.timeout(240000) });
    const html = await res.text();
    const text = sichtbarerText(html);
    const funde = [];
    for (const wort of ["NaN", "undefined", "Infinity", "[object Object]"]) {
      const re = new RegExp(`(^|[^A-Za-z])${wort.replace(/[.*+?^${}()|\\]/g, "\\$&")}([^A-Za-z]|$)`, "g");
      const m = text.match(re);
      if (m) {
        const i = text.search(re);
        funde.push(`${wort} ×${m.length} („…${text.slice(Math.max(0, i - 60), i + 60)}…“)`);
      }
    }
    const ok = res.status === 200 && funde.length === 0;
    if (!ok) fehler += 1;
    console.log(`${ok ? "OK  " : "FEHL"} ${res.status} ${pfad} (${((Date.now() - start) / 1000).toFixed(1)} s, ${Math.round(html.length / 1024)} KB)${funde.length ? "\n     " + funde.join("\n     ") : ""}`);
  } catch (e) {
    fehler += 1;
    console.log(`FEHL --- ${pfad}: ${e.message}`);
  }
}
console.log(fehler ? `\n${fehler} Seite(n) mit Fehlern` : "\nAlle Seiten in Ordnung");
process.exit(fehler ? 1 : 0);

