// T2 – Rechner & Tools: Laufzeitfehler, Interaktionen, wenige Aufnahmen.
// Aufruf: node t2_pruef.mjs [teil]   teil = alle | interaktion | fehler
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";

const BASIS = "http://localhost:3100";
const teil = process.argv[2] || "alle";
const shot = (name) => fileURLToPath(new URL(`./shots/${name}.png`, import.meta.url));
const b = await chromium.launch();
const ergebnis = [];
const log = (...a) => {
  console.log(...a);
  ergebnis.push(a.join(" "));
};

async function seite(breite) {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  p.fehler = [];
  p.on("pageerror", (e) => p.fehler.push("PAGEERROR " + e.message.slice(0, 300)));
  p.on("console", (m) => m.type() === "error" && p.fehler.push("CONSOLE " + m.text().slice(0, 300)));
  return p;
}
async function laden(p, pfad) {
  const r = await p.goto(BASIS + pfad, { waitUntil: "load", timeout: 180000 });
  try {
    await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 2500 });
  } catch {}
  await p.waitForTimeout(1500);
  return r.status();
}

try {
  if (teil === "alle" || teil === "interaktion") {
    // 1) PPA Desktop: Tastatur am Regler, URL-Zustand, Szenario-Vergleich, Delta
    {
      const p = await seite(1440);
      const st = await laden(p, "/rechner/ppa");
      const regler = p.locator('input[type="range"]').first();
      await regler.focus();
      await p.keyboard.press("ArrowRight");
      await p.keyboard.press("Shift+ArrowRight");
      await p.waitForTimeout(700);
      const blase = await p.evaluate(() => [...document.querySelectorAll("span.opacity-100")].some((s) => s.textContent.includes("MWh") || s.textContent.includes("GWh")));
      const delta = await p.evaluate(() => [...document.querySelectorAll("span")].some((s) => /▲|▼/.test(s.textContent) && s.className.includes("opacity-100")));
      await p.waitForTimeout(600);
      const url = p.url();
      await p.getByRole("button", { name: "Szenario merken & vergleichen" }).click();
      await p.waitForTimeout(400);
      await regler.focus();
      await p.keyboard.press("Shift+ArrowRight");
      await p.waitForTimeout(900);
      const vergleich = await p.locator("#szenario-vergleich").count();
      const geaendert = await p.locator("tr.bg-ov-50\\/70").count();
      await p.locator('section[aria-label="Rechner"]').scrollIntoViewIfNeeded();
      await p.evaluate(() => window.scrollBy(0, -90));
      await p.waitForTimeout(500);
      await p.screenshot({ path: shot("t2_ppa_1440") });
      log(`PPA 1440: Status ${st} · Wertblase ${blase} · Delta ${delta} · URL ${url.replace(BASIS, "")} · Vergleich ${vergleich} · geänderte Zeilen ${geaendert}`);
      if (p.fehler.length) log("  Fehler:", p.fehler.join(" | "));
      await p.context().close();
    }
    // 2) Geteilter Link wird wiederhergestellt
    {
      const p = await seite(1440);
      await laden(p, "/rechner/ppa?verbrauchMwh=5000&laufzeit=15&profil=unsinn");
      await p.waitForTimeout(800);
      const werte = await p.evaluate(() => [...document.querySelectorAll('input[type="range"]')].map((i) => i.value));
      log(`PPA Link: Reglerwerte ${werte.join(", ")} (erwartet 5000 … 15)`);
      if (p.fehler.length) log("  Fehler:", p.fehler.join(" | "));
      await p.context().close();
    }
    // 3) Solarpark mobil: klebende Ergebnisleiste unten
    {
      const p = await seite(390);
      await laden(p, "/rechner/solarpark");
      await p.locator('input[type="range"]').nth(2).scrollIntoViewIfNeeded();
      await p.waitForTimeout(900);
      const leiste = await p.evaluate(() => {
        const r = document.querySelector('[aria-label="Ergebnis in Kürze"]');
        const w = r?.parentElement;
        return w ? { sichtbar: w.className.includes("translate-y-0"), text: r.innerText.replace(/\s+/g, " ") } : null;
      });
      const ueberlauf = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      await p.screenshot({ path: shot("t2_solarpark_390") });
      log(`Solarpark 390: Leiste ${JSON.stringify(leiste)} · Überlauf ${ueberlauf}px`);
      // Zum Ergebnis springen
      await p.getByRole("button", { name: "Zum vollständigen Ergebnis" }).click();
      await p.waitForTimeout(1500);
      const nachSprung = await p.evaluate(() => document.querySelector('[aria-label="Ergebnis in Kürze"]')?.parentElement.className.includes("translate-y-0"));
      log(`  nach Sprung zum Ergebnis Leiste sichtbar: ${nachSprung}`);
      if (p.fehler.length) log("  Fehler:", p.fehler.join(" | "));
      await p.context().close();
    }
    // 4) Flächencheck mobil: Zahlenfeld, Live-Ampel, Neuladen
