      await p.getByRole("button", { name: /Weiter/ }).click();
      await p.waitForTimeout(700);
      const feld = p.locator("#fc-ha-genau");
      await feld.fill("");
      await feld.type("25");
      const zwischen = await feld.inputValue();
      await feld.blur();
      await p.waitForTimeout(300);
      await p.locator('label:has(input[name="nutzung"][value="konversion"])').click();
      await p.waitForTimeout(700);
      const regler = await p.locator('input[type="range"]').first().inputValue();
      const live = await p.evaluate(() => document.querySelector('[aria-live="polite"].mt-1\\.5, p[aria-live="polite"]')?.innerText);
      await feld.fill("");
      await feld.blur();
      await p.waitForTimeout(300);
      const fehlertext = await p.locator("#fc-ha-hilfe").innerText();
      await feld.fill("25,5");
      await feld.blur();
      await p.waitForTimeout(300);
      await p.locator("#fc-ha-genau").scrollIntoViewIfNeeded();
      await p.evaluate(() => window.scrollBy(0, -260));
      await p.screenshot({ path: shot("t2_flaechencheck_390") });
      await p.reload({ waitUntil: "load" });
      await p.waitForTimeout(2000);
      const nachReload = await p.evaluate(() => ({ feld: document.querySelector("#fc-ha-genau")?.value, schritt: document.querySelector("[aria-current=step]")?.innerText }));
      log(`Flächencheck 390: Feld nach „25“ = ${zwischen} · Regler ${regler} · Live: ${live?.slice(0, 90)} · leer → „${fehlertext}“ · nach Neuladen ${JSON.stringify(nachReload)}`);
      if (p.fehler.length) log("  Fehler:", p.fehler.join(" | "));
      await p.context().close();
    }
    // 5) Hub Desktop (sichtbarer Bereich unter dem Hero)
    {
      const p = await seite(1440);
      const st = await laden(p, "/rechner");
      const anzahl = await p.locator('section[aria-label="Alle Rechner und Tools"] a[href^="/"]').count();
      await p.evaluate(() => window.scrollTo(0, 420));
      await p.waitForTimeout(900);
      await p.screenshot({ path: shot("t2_hub_1440") });
      log(`Hub 1440: Status ${st} · Tool-Links ${anzahl}`);
      if (p.fehler.length) log("  Fehler:", p.fehler.join(" | "));
      await p.context().close();
    }
  }

  if (teil === "alle" || teil === "fehler") {
    // 6) Laufzeitfehler auf allen Rechnern und Seiten mit geteilten Bausteinen
    const p = await seite(1440);
    for (const pfad of [
      "/rechner/solarpark",
      "/rechner/kommune",
      "/rechner/solarcarport",
      "/rechner/energy-sharing",
      "/rechner/netzanschluss",
      "/rechner/grossspeicher",
      "/rechner/beteiligung",
      "/rechner/pachtangebot-check",
      "/rechner/projektbewertung",
      "/rechner/bestandsanlage",
      "/rechner/dachpacht",
      "/rechner/agri-pv",
      "/rechner/pacht",
      "/rechner/reststrom",
      "/energiegemeinschaften/rechner",
      "/marktdaten",
    ]) {
      p.fehler = [];
      let st = "-";
      try {
        st = await laden(p, pfad);
        // Einmal mit Tastatur am ersten Regler drehen und ein Diagramm fokussieren
        const r = p.locator('input[type="range"]').first();
        if (await r.count()) {
          await r.focus();
          await p.keyboard.press("ArrowRight");
        }
        const d = p.locator('[role="group"][tabindex="0"]').first();
        if (await d.count()) {
          await d.focus();
          await p.keyboard.press("ArrowRight");
        }
        await p.waitForTimeout(600);
      } catch (e) {
        p.fehler.push("SKRIPT " + e.message.slice(0, 200));
      }
